// @pit: {"label": "Forward S&P outcomes after the closest non-2000 shape matches"}
async ({ http: { request } }) => {
  const H = { "User-Agent": "Mozilla/5.0" };
  const ts = (d: string) => Math.floor(Date.parse(d) / 1000);
  const ends = ["1957-01-21", "1966-04-28", "1987-10-19", "1999-07-07", "2000-05-04", "2015-08-11", "2020-01-08"];
  const out = await Promise.all(ends.map(async (e) => {
    const z = new Date(Date.parse(e) + 400 * 864e5).toISOString().slice(0, 10);
    const j = JSON.parse((await request(`https://query1.finance.yahoo.com/v8/finance/chart/%5EGSPC?period1=${ts(e)}&period2=${ts(z)}&interval=1d`, { maxBytes: 1_000_000, headers: H })).body).chart.result[0];
    const c = (j.indicators.quote[0].close as number[]).filter((x) => x != null); const d = j.timestamp.map((t: number) => new Date(t * 1000).toISOString().slice(0, 10));
    const n = Math.min(252, c.length - 1); const w = c.slice(0, n + 1); const mn = Math.min(...w);
    return { end: e, start: d[0], ret12m: Math.round((w[n] / w[0] - 1) * 1000) / 10, worst12m: Math.round((mn / w[0] - 1) * 1000) / 10, worstOn: d[c.indexOf(mn)] };
  }));
  return out as PitJsonValue;
}
